// Lossless BufferGeometry data, generated by the shipped renderer. GPU objects,
// skeletons and animation state are still created by the original game code.
const TYPES = { Float32Array, Uint32Array, Uint16Array, Uint8Array };
const ATTRIBUTES = {
  position: 3, normal: 3, uv: 2, color: 3, aux: 4, aux2: 3,
  skinIndex: 4, skinWeight: 4,
};
const MAX_BYTES = 16 * 1024 * 1024;
const aligned = n => Math.ceil(n / 8) * 8;
function filterPixels(data, width, decode = false) {
  const result = new Uint8Array(data.length), stride = width * 4;
  const source = decode ? result : data;
  for (let i = 0; i < data.length; i++) {
    const edge = i % stride < 4;
    const left = edge ? 0 : source[i - 4], up = i < stride ? 0 : source[i - stride];
    const corner = edge || i < stride ? 0 : source[i - stride - 4];
    const prediction = left + up - corner;
    const a = Math.abs(prediction - left), b = Math.abs(prediction - up), c = Math.abs(prediction - corner);
    const nearest = a <= b && a <= c ? left : b <= c ? up : corner;
    result[i] = decode ? data[i] + nearest : data[i] - nearest;
  }
  return result;
}

export function encodeOperators(geometries, source, grips = [], materials = null) {
  const chunks = [];
  let length = 0;
  function array(value) {
    const type = value.constructor.name;
    if (!Object.hasOwn(TYPES, type)) throw Error("Unsupported geometry array");
    // Both teams share most mesh data. Deduplicate exact bytes during authoring.
    const same = chunks.find(chunk => chunk.value.constructor === value.constructor &&
      chunk.value.length === value.length && chunk.value.every((v, i) => Object.is(v, value[i])));
    if (same) return { type, offset: same.offset, length: value.length };
    const record = { type, offset: length, length: value.length };
    chunks.push({ offset: length, value });
    length += aligned(value.byteLength);
    return record;
  }
  const operators = geometries.map(geometry => ({
    attributes: Object.fromEntries(Object.entries(geometry.attributes).map(([name, attr]) =>
      [name, { ...array(attr.array), itemSize: attr.itemSize, normalized: attr.normalized }],
    )),
    index: array(geometry.index.array),
    fp: array(geometry.userData.fp),
    drawRange: geometry.drawRange,
    triangles: geometry.userData.triangles,
  }));
  // A PNG-style predictor makes HTTP gzip effective on normal/camo maps,
  // without lossy compression or canvas alpha/color conversion.
  const pixels = materials && { ...materials, textures: materials.textures.map(record => ({ ...record, encoding: "paeth", data: array(filterPixels(record.data, record.width)) })) };
  const header = new TextEncoder().encode(JSON.stringify({ schema: 1, source, operators, grips, materials: pixels }));
  const start = 8 + aligned(header.byteLength);
  const buffer = new ArrayBuffer(start + length), bytes = new Uint8Array(buffer);
  new DataView(buffer).setUint32(0, header.byteLength, true);
  bytes.set(header, 8);
  for (const chunk of chunks)
    bytes.set(new Uint8Array(chunk.value.buffer, chunk.value.byteOffset, chunk.value.byteLength), start + chunk.offset);
  return buffer;
}

export function decodeOperators(buffer, source) {
  if (!(buffer instanceof ArrayBuffer) || buffer.byteLength < 8 || buffer.byteLength > MAX_BYTES)
    throw Error("Invalid operator pack size");
  const length = new DataView(buffer).getUint32(0, true), start = 8 + aligned(length);
  if (length > 64000 || start > buffer.byteLength) throw Error("Invalid operator header");
  const header = JSON.parse(new TextDecoder().decode(new Uint8Array(buffer, 8, length)));
  if (header.schema !== 1 || header.source !== source || header.operators?.length !== 2)
    throw Error("Obsolete operator pack");
  function array(record) {
    if (!record || !Object.hasOwn(TYPES, record.type)) throw Error("Invalid geometry type");
    const Type = TYPES[record.type];
    if (!Number.isInteger(record.offset) || record.offset < 0 || record.offset % 8 ||
        !Number.isInteger(record.length) || record.length < 1 ||
        start + record.offset + record.length * Type.BYTES_PER_ELEMENT > buffer.byteLength)
      throw Error("Invalid geometry array");
    // Views share the downloaded buffer; no JSON number arrays or extra copies.
    return new Type(buffer, start + record.offset, record.length);
  }
  const operators = header.operators.map(record => {
    const attributes = {};
    for (const [name, size] of Object.entries(ATTRIBUTES)) {
      const attr = record.attributes?.[name], data = array(attr);
      if (attr.itemSize !== size || data.length % size || attr.normalized !== false ||
          !(name === "skinIndex" ? data instanceof Uint16Array : data instanceof Float32Array))
        throw Error("Invalid operator attribute");
      attributes[name] = { data, itemSize: size, normalized: attr.normalized };
    }
    const vertices = attributes.position.data.length / 3;
    if (Object.values(attributes).some(attr => attr.data.length / attr.itemSize !== vertices))
      throw Error("Inconsistent operator vertices");
    const index = array(record.index), fp = array(record.fp), { start: from, count } = record.drawRange || {};
    if (!(index instanceof Uint16Array || index instanceof Uint32Array) || index.length % 3 ||
        !(fp instanceof Uint8Array) || fp.length !== vertices ||
        !Number.isInteger(from) || from < 0 || !Number.isInteger(count) || count < 0 ||
        from + count > index.length || count % 3 || record.triangles !== count / 3)
      throw Error("Invalid operator indices");
    for (const vertex of index) if (vertex >= vertices) throw Error("Invalid operator vertex reference");
    return { attributes, index, fp, drawRange: { start: from, count }, triangles: record.triangles };
  });
  operators.grips = header.grips || [];
  operators.materials = header.materials && {
    ...header.materials,
    textures: header.materials.textures.map(record => ({ ...record,
      data: record.encoding === "paeth" ? filterPixels(array(record.data), record.width, true) : array(record.data),
    })),
  };
  return operators;
}

const gripKey = (kind, build) => JSON.stringify([kind, ...["optic", "muzzle", "underbarrel", "magazine", "stock", "camo"].map(key => build?.[key] || "-")]);
export function captureGrips(kind, gun) {
  function visit(value) {
    if (value?.isVector3) return { vector: value.toArray() };
    if (value?.isQuaternion) return { quaternion: value.toArray() };
    if (ArrayBuffer.isView(value)) return Array.from(value);
    if (Array.isArray(value)) return value.map(visit);
    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value)
      .filter(([, child]) => typeof child !== "function").map(([key, child]) => [key, visit(child)]));
    return value;
  }
  return { key: gripKey(kind, gun.build), grips: visit(gun.grips) };
}

export function hydrateGrips(kind, gun, packs, createVector, createQuaternion) {
  const pack = packs?.find(pack => pack.key === gripKey(kind, gun.build));
  if (!pack) return false;
  function visit(value) {
    if (value?.vector) return createVector().fromArray(value.vector);
    if (value?.quaternion) return createQuaternion().fromArray(value.quaternion);
    if (Array.isArray(value)) return value.map(visit);
    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, visit(child)]));
    return value;
  }
  const grips = visit(pack.grips);
  if (!grips?.fire || !(grips.support || grips.pump)) return false;
  if (kind === "pistol" && (!grips.mag || !grips.rack || !grips.frag)) return false;
  for (const grip of Object.values(grips)) {
    if (!grip.pos?.isVector3 || !grip.quat?.isQuaternion || !Array.isArray(grip.pose) ||
        grip.pose.length !== 22 || !grip.pose.every(Number.isFinite)) return false;
    grip.pose = new Float32Array(grip.pose);
  }
  // Distance-field callbacks are only used by authoring diagnostics; gameplay
  // consumes the original positions, quaternions and poses. Tuning bypasses us.
  gun.grips = grips;
  gun.bakeTimes = {};
  gun.bakeMs = 0;
  gun.miss = {};
  gun.need = () => gun.grips;
  gun.bakeAll = () => gun.grips;
  return true;
}

export function restoreOperator(record, createGeometry, createAttribute) {
  if (!record) return null;
  const geometry = createGeometry();
  for (const [name, attr] of Object.entries(record.attributes))
    geometry.setAttribute(name, createAttribute(attr.data, attr.itemSize, attr.normalized));
  geometry.setIndex(createAttribute(record.index, 1, false));
  geometry.setDrawRange(record.drawRange.start, record.drawRange.count);
  geometry.userData.fp = record.fp;
  geometry.userData.triangles = record.triangles;
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
  return geometry;
}
